from pathlib import Path
s=Path('baseline/clique_early.cpp').read_text()
s=s.replace('int main(int argc,char**argv){','int root_begin=0,root_end=1000000,root_mod=1,root_residue=0;\nbool root_traces=false;\nint main(int argc,char**argv){')
s=s.replace('target=atoi(argv[2]);', 'if(argc>=9){root_begin=atoi(argv[7]);root_end=atoi(argv[8]);}\n if(argc>=11){root_mod=atoi(argv[9]);root_residue=atoi(argv[10]);}\n if(argc>=12)root_traces=atoi(argv[11]);\n target=atoi(argv[2]);')
s=s.replace('if(argc>=6 && string(argv[5])=="proof"){','if(argc>=6 && string(argv[5])=="proof" && !root_traces){')
s=s.replace('started=chrono::steady_clock::now();bool found=false;int roots=0,cut_roots=0;', 'started=chrono::steady_clock::now();bool found=false;int roots=0,cut_roots=0,ordinal=-1;\n ofstream rootlog(prefix+".roots.jsonl");')
s=s.replace('if(sym && rep[i]!=i)continue;','if(sym && rep[i]!=i)continue;\n  ordinal++;if(ordinal<root_begin || ordinal>=root_end || ordinal%root_mod!=root_residue)continue;')
s=s.replace('path={i};root_cut=false;', 'uint64_t nodes_before=nodes;double root_wall=elapsed();\n  if(root_traces){proof=gzopen((prefix+".r"+to_string(ordinal)+".proof.gz").c_str(),"wb1");if(!proof)return 3;}\n  path={i};root_cut=false;')
s=s.replace('if(root_cut)cut_roots++;', 'if(root_cut)cut_roots++;\n  rootlog<<"{\\"ordinal\\":"<<ordinal<<",\\"vertex\\":"<<i<<",\\"nodes\\":"<<nodes-nodes_before<<",\\"seconds\\":"<<elapsed()-root_wall<<",\\"complete\\":"<<(!found&&!timeout&&!root_cut?"true":"false")<<"}\\n";rootlog.flush();\n  if(root_traces){gzclose(proof);proof=nullptr;}')
s=s.replace('if(status=="EXHAUSTED")gzwrite', 'if(status=="EXHAUSTED" && root_begin==0 && root_end>=m && root_mod==1)gzwrite')
Path('baseline/timed_baseline.cpp').write_text(s)
s=s.replace('#include "small_early.hpp"','#include "local64.hpp"')
s=s.replace('if(pop(p)<=128){int vertices[128],len=0;for(int j=0;j<W;j++){uint64_t w=p[j];while(w){int v=64*j+__builtin_ctzll(w);w&=w-1;vertices[len++]=v;}}return expand_small_vector(vertices,len);}', 'if(pop(p)<=LOCAL_THRESHOLD){Local64 kernel(p);return kernel.expand(kernel.initial);}')
Path('src/clique_speed.cpp').write_text(s)
